const gallery=[{image:'assets/beauty-2.jpg',caption:'The soft-glam mood',alt:'Makeup and beauty essentials'},{image:'assets/beauty-3.jpg',caption:'At your fingertips',alt:'Detailed manicure with glossy nail colour'},{image:'assets/beauty-0.jpg',caption:'Good hair energy',alt:'Portrait with long flowing hair'}];
const hours=Array.from({length:7},(_,day)=>({day,closed:day===0,open:'09:00',close:day===6?'16:00':'18:00'}));
const defaults=Object.fromEntries(fields.map(([key,label,group,type,value])=>[key,value]));defaults.gallery=gallery;defaults.hours=hours;
window.BloomContent={fields,defaults,merge:v=>({...structuredClone(defaults),...v}),safeImage:v=>typeof v==='string'&&(/^(assets\/|https:\/\/)/.test(v))};
